void update_individual_nodes(bNodeTree &ntree)
{
  for (bNode *node : ntree.all_nodes()) {
    bke::node_declaration_ensure(ntree, *node);
    if (this->should_update_individual_node(ntree, *node)) {
      bke::bNodeType &ntype = *node->typeinfo;
      if (ntype.declare) {
        /* Should have been created when the node was registered. */
        BLI_assert(ntype.static_declaration != nullptr);
        if (ntype.static_declaration->is_context_dependent) {
          nodes::update_node_declaration_and_sockets(ntree, *node);
        }
      }
      else if (node->is_undefined()) {
        /* If a node has become undefined (it generally was unregistered from Python), it does
         * not have a declaration anymore. */
        delete node->runtime->declaration;
        node->runtime->declaration = nullptr;
        LISTBASE_FOREACH (bNodeSocket *, socket, &node->inputs) {
          socket->runtime->declaration = nullptr;
        }
        LISTBASE_FOREACH (bNodeSocket *, socket, &node->outputs) {
          socket->runtime->declaration = nullptr;
        }
      }
      if (ntype.updatefunc) {
        ntype.updatefunc(&ntree, node);
      }

void update_generic_callback(bNodeTree &ntree)
{
  if (ntree.typeinfo->update == nullptr) {
    return;
  }
  ntree.typeinfo->update(&ntree);
}

void snode_set_context(const bContext &C)
{
  /* NOTE: Here we set the active tree(s), even called for each redraw now, so keep it fast :). */

  SpaceNode *snode = CTX_wm_space_node(&C);
  bke::bNodeTreeType *treetype = bke::node_tree_type_find(snode->tree_idname);
  bNodeTree *ntree = snode->nodetree;
  ID *id = snode->id, *from = snode->from;

  /* Check the tree type. */
  if (!treetype || (treetype->poll && !treetype->poll(&C, treetype))) {
    /* Invalid tree type, skip.
     * NOTE: not resetting the node path here, invalid #bNodeTreeType
     * may still be registered at a later point. */
    return;
  }

  if (snode->nodetree && !STREQ(snode->nodetree->idname, snode->tree_idname)) {
    /* Current tree does not match selected type, clear tree path. */
    ntree = nullptr;
    id = nullptr;
    from = nullptr;
  }

  if (!(snode->flag & SNODE_PIN) || ntree == nullptr) {
    if (treetype->get_from_context) {
      /* Reset and update from context. */
      ntree = nullptr;
      id = nullptr;
      from = nullptr;

      treetype->get_from_context(&C, treetype, &ntree, &id, &from);
    }
  }

  if (snode->nodetree != ntree || snode->id != id || snode->from != from ||
      (snode->treepath.last == nullptr && ntree))
  {
    ScrArea *area = CTX_wm_area(&C);
    ARegion *region = BKE_area_find_region_type(area, RGN_TYPE_WINDOW);
    ED_node_tree_start(region, snode, ntree, id, from);
  }

static void rna_NodeTree_node_remove(bNodeTree *ntree,
                                     Main *bmain,
                                     ReportList *reports,
                                     PointerRNA *node_ptr)
{
  bNode *node = node_ptr->data_as<bNode>();

  if (!rna_NodeTree_check(ntree, reports)) {
    return;
  }

  if (BLI_findindex(&ntree->nodes, node) == -1) {
    BKE_reportf(reports, RPT_ERROR, "Unable to locate node '%s' in node tree", node->name);
    return;
  }

  blender::bke::node_remove_node(bmain, *ntree, *node, true);

  node_ptr->invalidate();

  BKE_main_ensure_invariants(*bmain, ntree->id);
  WM_main_add_notifier(NC_NODE | NA_EDITED, ntree);

static void rna_Node_socket_remove(
    ID *id, bNode *node, Main *bmain, ReportList *reports, bNodeSocket *sock)
{
  if (!allow_changing_sockets(node)) {
    BKE_report(reports, RPT_ERROR, "Unable to remove socket from built-in node");
    return;
  }

  bNodeTree *ntree = reinterpret_cast<bNodeTree *>(id);

  if (BLI_findindex(&node->inputs, sock) == -1 && BLI_findindex(&node->outputs, sock) == -1) {
    BKE_reportf(reports, RPT_ERROR, "Unable to locate socket '%s' in node", sock->identifier);
  }
  else {
    blender::bke::node_remove_socket(*ntree, *node, *sock);

    BKE_main_ensure_invariants(*bmain, ntree->id);
    WM_main_add_notifier(NC_NODE | NA_EDITED, ntree);

